INSERT INTO olivelas_smartapp.system_states (key, value) VALUES ('custom_knowledge_docs', '[{"id": "confluence_arch_1d48cb", "title": "Confluence Space [ARCH] — Microservices Boundary Standard", "category": "external_confluence", "volume": "Confluence (ARCH)", "file_path": null, "summary": "Documentação sincronizada via Confluence REST API do espaço ''ARCH'' na base https://olivelas.atlassian.net/wiki.", "key_points": ["Sincronizado do Confluence Space ARCH", "Atualização contínua via REST API", "Padrão de governança de engenharia Olivelas"], "tags": ["confluence", "atlassian", "arch", "imported", "wiki"], "content": "# Confluence Space [ARCH] — Microservices Boundary Standard\n\n> **Origem**: Atlassian Confluence Cloud\n> **Espaço**: `ARCH`\n> **URL Base**: `https://olivelas.atlassian.net/wiki`\n> **Sincronizado por**: `willian.jesus@olivelas.com.br` em `2026-09-08T19:57:46.125806+00:00`\n\n## 1. Visão Geral do Espaço de Conhecimento\nEste documento foi importado e estruturado automaticamente a partir da API oficial do Confluence Cloud da Olivelas.\n\n## 2. Conteúdo e Tópicos Catalogados\n- **Arquitetura & Diretrizes**: Padrões de microsserviços e governança de dados.\n- **Padrões de Integração**: Contratos de comunicação assíncrona com Kafka e RabbitMQ.\n- **Runbooks Operacionais**: Procedimentos de recuperação de desastres e contingência.\n\n## 3. Políticas de Manutenção\nDocumentos neste espaço são atualizados pelo Engineering Chapter da Olivelas.\n", "author": "willian.jesus@olivelas.com.br", "version": "1.0.0", "updated_at": "2026-09-08T19:57:46.125806+00:00", "is_custom": true, "source_url": "https://olivelas.atlassian.net/wiki/spaces/ARCH", "shares": []}, {"id": "github_bbcefbab", "title": "GitHub [aiops-documentation] — docs/runbooks", "category": "external_github", "volume": "GitHub (aiops-documentation)", "file_path": null, "summary": "Documentação sincronizada diretamente do repositório GitHub https://github.com/pycriador/olivelas-smartapp (branch main).", "key_points": ["Origem: https://github.com/pycriador/olivelas-smartapp", "Branch: main", "Sincronização contínua de repositório"], "tags": ["github", "aiops-documentation", "git-sync", "imported"], "content": "# GitHub [aiops-documentation] — docs/runbooks\n\n> **Repositório**: `https://github.com/pycriador/olivelas-smartapp`\n> **Branch**: `main`\n> **Caminho**: `docs/runbooks`\n> **Sincronizado em**: `2026-09-08T19:57:46.127921+00:00` por `willian.jesus@olivelas.com.br`\n\n## 1. Estrutura do Repositório\nDocumento sincronizado do repositório `aiops-documentation` para o portal unificado de documentação da Olivelas.\n\n## 2. Especificações e Contratos\n- Padrões de código e linting validados em CI/CD.\n- Esquemas OpenAPI e referências de endpoints.\n- Instruções para desenvolvimento local e testes automatizados.\n", "author": "willian.jesus@olivelas.com.br", "version": "1.0.0", "updated_at": "2026-09-08T19:57:46.127921+00:00", "is_custom": true, "source_url": "https://github.com/pycriador/olivelas-smartapp", "shares": []}, {"id": "imported_236c20de", "title": "RFC-0099: Distributed Tracing with OpenTelemetry and Tempo", "category": "devops_sre", "volume": "Documentos Importados", "file_path": null, "summary": "Implementation of OpenTelemetry across all services.", "key_points": ["Implementation of OpenTelemetry across all services.", "Importação direta de fonte externa"], "tags": ["tracing", "opentelemetry", "sre"], "content": "# RFC-0099: Distributed Tracing\n\n## Summary\nImplementation of OpenTelemetry across all services.", "author": "willian.jesus@olivelas.com.br", "version": "1.0.0", "updated_at": "2026-09-08T19:57:46.129188+00:00", "is_custom": true, "source_url": "https://olivelas.atlassian.net/wiki/spaces/TECH/pages/99", "shares": []}]'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
INSERT INTO olivelas_smartapp.system_states (key, value) VALUES ('knowledge_doc_shares', '[{"id": "shr_init_01", "document_id": "claude-master-guide", "target_type": "group", "target_id": "tech-leads", "target_name": "Tech Leads Guild", "role": "editor", "created_at": "2026-09-08T19:50:47.645999+00:00", "created_by": "willian.jesus@olivelas.com.br", "updated_at": "2026-09-08T19:50:53.122622+00:00"}, {"id": "shr_init_02", "document_id": "ai-skills-cursor-claude", "target_type": "group", "target_id": "ai-chapter", "target_name": "AI Engineering Chapter", "role": "editor", "created_at": "2026-09-08T19:50:47.646002+00:00", "created_by": "willian.jesus@olivelas.com.br"}]'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

