INSERT INTO olivelas_smartapp.architectures (id, name, slug, category, description, version, status, characteristics, recommended_for, restrictions, layers, recommended_modules, canonical_folder_structure, folder_tree, modules, components, rules, specifications, versions) VALUES ('arch_loft_postgres_opsbase_fullstack', 'Olivelas Enterprise Fullstack (React 19 + FastAPI + PostgreSQL via Olivelas Opsbase)', 'loft-postgres-opsbase-fullstack', 'Fullstack Architecture', 'Arquitetura corporativa de alta disponibilidade com provisionamento gerenciado de PostgreSQL 16 via Olivelas Opsbase (/api/opsbase/v1/databases), SQLAlchemy 2.0, Alembic, RBAC completo e trilha de auditoria.', '1.0.0', 'Published', '["Banco de dados PostgreSQL 16 provisionado e gerenciado via Olivelas Opsbase", "Autenticação JWT HS256 com Lockout 423 e RBAC granular", "Migrações versionadas via Alembic e transações ACID via Unit of Work", "Trilha de auditoria completa em todas as mutações"]'::jsonb, '["Aplicações Enterprise com PostgreSQL", "Plataformas CRUD Multi-Tenant", "Sistemas Integrados ao Olivelas Opsbase"]'::jsonb, '["Exige conexão PostgreSQL gerenciada ou container compatível", "Obrigatório uso de migrações Alembic"]'::jsonb, '["Presentation (React 19 + Ant Design 5 + Olivelas Tokens)", "API Gateway & FastAPI Routers (Bearer JWT + RBAC)", "Domain & Application Services (Auth, IAM, Audit, Business)", "Managed Persistence (PostgreSQL 16 via Olivelas Opsbase + SQLAlchemy 2.0 + Alembic)"]'::jsonb, '["mod_layout_navigation", "mod_data_table_filtering", "mod_auth_identity_be"]'::jsonb, '["frontend/src", "app/api", "app/services", "app/storage", "app/models", "alembic/versions"]'::jsonb, '├── frontend/src
