from typing import Any
from datetime import datetime, timezone
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session
from app.core.errors import ValidationError, NotFoundError

class AgentPolicyInput(BaseModel):
    resource_id: str = Field(..., min_length=1, description="Identificador canônico do recurso")
    actor_email: str = Field(..., description="E-mail do ator autenticado via JWT")
    parameters: dict[str, Any] = Field(default_factory=dict)

class AgentPolicyOutput(BaseModel):
    resource_id: str
    component: str = "cmp_be_agent_policy"
    status: str = "completed"
    processed_at: str
    result: dict[str, Any]

class AgentPolicy:
    """Componente backend oficial AgentPolicy padronizado da Olivelas."""
    def __init__(self, db_session: Session | None = None) -> None:
        self.db = db_session

    def validate_input(self, payload: dict[str, Any]) -> AgentPolicyInput:
        if not isinstance(payload, dict) or not payload.get("resource_id"):
            raise ValidationError("Campo obrigatório ''resource_id'' ausente.", details={"component": "cmp_be_agent_policy"})
        return AgentPolicyInput(**payload)

    async def execute(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Executa a regra de negócio canônica do componente AgentPolicy."""
        validated = self.validate_input(payload)
        output = AgentPolicyOutput(
            resource_id=validated.resource_id,
            processed_at=datetime.now(timezone.utc).isoformat(),
            result={"actor": validated.actor_email, **validated.parameters},
        )
        return output.model_dump()

router = APIRouter(prefix="/api/v1/agent-policy", tags=["Authentication & Identity"])

@router.post("/execute")
async def execute_agent_policy(
    payload: dict,
    request: Request,
    session: Session = Depends(get_db_session),
):
    """Endpoint canônico para AgentPolicy seguindo ApiResponse envelope."""
    service = AgentPolicy(db_session=session)
    result = await service.execute(payload)
    return ApiResponse(data=result, meta=build_meta(getattr(request.state, "request_id", None)))', 'Toda execução de agent deve possuir:

