Autenticação obrigatória.\")\n        role = user_context.get(\"role\", \"Viewer\")\n        perms = set(user_context.get(\"permissions\") or cls.ROLE_MATRIX.get(role, []))\n        return \"*\" in perms or permission in perms\n\n    @classmethod\n    def require_permission(cls, user_context: dict, permission: str) -> bool:\n        if not cls.has_permission(user_context, permission):\n            raise AuthorizationError(\n                f\"Permissão insuficiente: requer ''{permission}''.\",\n                details={\"required_permission\": permission, \"role\": user_context.get(\"role\")},\n            )\n        return True\n", "methods": [{"name": "get_user_permissions", "signature": "get_user_permissions(session: Session, user: UserModel) -> list[str]", "inputs": {"user": "UserModel (role, groups)"}, "outputs": {"permissions": "list[str] (ex.: [''projects:read'', ''projects:create'', ''blueprints:validate''])"}, "errors": []}, {"name": "require_permission", "signature": "require_permission(user_context: dict, required_permission: str) -> bool", "inputs": {"user_context": "dict (from verify_token_and_get_user)", "required_permission": "str"}, "outputs": {"granted": "bool"}, "errors": [{"code": "AUTHENTICATION_FAILED", "http_status": 401, "when": "Contexto de usuário não autenticado"}, {"code": "PERMISSION_DENIED", "http_status": 403, "when": "Papel/grupo do usuário não possui a permissão exigida"}]}], "reference_repository": "app_builder_engine/app/services/rbac_service.py"}'::jsonb, 'from app.core.errors import AuthenticationError, AuthorizationError

class PermissionService:
    """Serviço RBAC de resolução de matriz Papel -> Permissões e guardas de autorização."""
    ROLE_MATRIX: dict[str, list[str]] = {
        "Global Admin": ["*"],
        "Admin": ["users:read", "users:create", "users:update", "groups:read", "groups:update", "projects:read", "projects:create", "projects:update", "blueprints:read", "blueprints:create", "blueprints:validate", "audit:read"],
        "Editor": ["projects:read", "projects:create", "projects:update", "blueprints:read", "blueprints:create", "blueprints:validate", "components:read", "modules:read", "templates:read"],
        "Viewer": ["projects:read", "blueprints:read", "components:read", "modules:read", "templates:read", "rules:read", "specifications:read", "architectures:read", "audit:read"],
    }

    @classmethod
    def has_permission(cls, user_context: dict, permission: str) -> bool:
        if not user_context or not user_context.get("id"):
            raise AuthenticationError("Autenticação obrigatória.")
        role = user_context.get("role", "Viewer")
        perms = set(user_context.get("permissions") or cls.ROLE_MATRIX.get(role, []))
        return "*" in perms or permission in perms

    @classmethod
    def require_permission(cls, user_context: dict, permission: str) -> bool:
        if not cls.has_permission(user_context, permission):
            raise AuthorizationError(
                f"Permissão insuficiente: requer ''{permission}''.",
                details={"required_permission": permission, "role": user_context.get("role")},
            )
        return True
