from sqlalchemy.orm import Session
from app.storage.db_engine import get_db_session
from app.schemas.response_envelope import ApiResponse, build_meta

from typing import Any
from datetime import datetime, timezone
from pydantic import BaseModel, Field
from sqlalchemy.orm import Session
from app.core.errors import ValidationError, NotFoundError

class PolicyServiceInput(BaseModel):
    resource_id: str = Field(..., min_length=1, description="Identificador canônico do recurso")
    actor_email: str = Field(..., description="E-mail do ator autenticado via JWT")
    parameters: dict[str, Any] = Field(default_factory=dict)

class PolicyServiceOutput(BaseModel):
    resource_id: str
    component: str = "cmp_be_policy_service"
    status: str = "completed"
    processed_at: str
    result: dict[str, Any]

class PolicyService:
    """Componente backend oficial PolicyService padronizado da Olivelas."""
    def __init__(self, db_session: Session | None = None) -> None:
        self.db = db_session

    def validate_input(self, payload: dict[str, Any]) -> PolicyServiceInput:
        if not isinstance(payload, dict) or not payload.get("resource_id"):
            raise ValidationError("Campo obrigatório ''resource_id'' ausente.", details={"component": "cmp_be_policy_service"})
        return PolicyServiceInput(**payload)

    async def execute(self, payload: dict[str, Any]) -> dict[str, Any]:
        """Executa a regra de negócio canônica do componente PolicyService."""
        validated = self.validate_input(payload)
        output = PolicyServiceOutput(
            resource_id=validated.resource_id,
            processed_at=datetime.now(timezone.utc).isoformat(),
            result={"actor": validated.actor_email, **validated.parameters},
        )
        return output.model_dump()

router = APIRouter(prefix="/api/v1/policy-service", tags=["Authentication & Identity"])

@router.post("/execute")
async def execute_policy_service(
    payload: dict,
    request: Request,
    session: Session = Depends(get_db_session),
):
    """Endpoint canônico para PolicyService seguindo ApiResponse envelope."""
    service = PolicyService(db_session=session)
    result = await service.execute(payload)
    return ApiResponse(data=result, meta=build_meta(getattr(request.state, "request_id", None)))', 'Responsável por regras de autorização mais complexas.

