oad, separators=(\",\", \":\")).encode()).rstrip(b\"=\").decode()\n        sig = hmac.new(settings.jwt_secret.encode(), f\"{h_b64}.{p_b64}\".encode(), hashlib.sha256).digest()\n        s_b64 = base64.urlsafe_b64encode(sig).rstrip(b\"=\").decode()\n        return f\"{h_b64}.{p_b64}.{s_b64}\", jti, exp\n\n    @classmethod\n    def decode_jwt_token(cls, token: str) -> dict:\n        parts = (token or \"\").split(\".\")\n        if len(parts) != 3:\n            raise AuthenticationError(\"Formato de token JWT inválido.\")\n        h_b64, p_b64, s_b64 = parts\n        expected_sig = hmac.new(settings.jwt_secret.encode(), f\"{h_b64}.{p_b64}\".encode(), hashlib.sha256).digest()\n        expected_b64 = base64.urlsafe_b64encode(expected_sig).rstrip(b\"=\").decode()\n        if not hmac.compare_digest(s_b64, expected_b64):\n            raise AuthenticationError(\"Assinatura do token JWT inválida.\")\n        pad = \"=\" * (-len(p_b64) % 4)\n        payload = json.loads(base64.urlsafe_b64decode(p_b64 + pad).decode())\n        if payload.get(\"exp\", 0) < int(datetime.now(timezone.utc).timestamp()):\n            raise AuthenticationError(\"Token JWT expirado.\")\n        return payload\n", "methods": [{"name": "create_jwt_token", "signature": "create_jwt_token(user_id: str, email: str, role: str, token_type: str = ''access'') -> tuple[str, str, datetime]", "inputs": {"user_id": "str", "email": "str", "role": "str", "token_type": "''access'' | ''refresh''"}, "outputs": {"token": "str (JWT HS256)", "jti": "str", "expires_at": "datetime"}, "errors": []}, {"name": "decode_jwt_token", "signature": "decode_jwt_token(token: str) -> dict", "inputs": {"token": "str"}, "outputs": {"sub": "str", "email": "str", "role": "str", "type": "str", "jti": "str", "iat": "int", "exp": "int"}, "errors": [{"code": "AUTHENTICATION_FAILED", "http_status": 401, "when": "Assinatura inválida, token malformado ou expirado"}]}], "reference_repository": "app_builder_engine/app/services/iam_service.py"}'::jsonb, 'import base64
import hashlib
import hmac
import json
import uuid
from datetime import datetime, timedelta, timezone
from app.core.config import settings
from app.core.errors import AuthenticationError

class TokenService:
    """Serviço canônico de emissão, assinatura HMAC-SHA256 (HS256) e verificação de tokens JWT."""
    ALGORITHM = "HS256"

    @classmethod
    def create_jwt_token(cls, user_id: str, email: str, role: str, token_type: str = "access") -> tuple[str, str, datetime]:
        now = datetime.now(timezone.utc)
        jti = f"jti_{uuid.uuid4().hex[:16]}"
        exp = now + (timedelta(hours=settings.jwt_expiration_hours) if token_type == "access" else timedelta(days=settings.jwt_refresh_expiration_days))
        header = {"alg": cls.ALGORITHM, "typ": "JWT"}
        payload = {"sub": user_id, "email": email, "role": role, "type": token_type, "jti": jti, "iat": int(now.timestamp()), "exp": int(exp.timestamp())}
        h_b64 = base64.urlsafe_b64encode(json.dumps(header, separators=(",", ":")).encode()).rstrip(b"=").decode()
        p_b64 = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode()).rstrip(b"=").decode()
        sig = hmac.new(settings.jwt_secret.encode(), f"{h_b64}.{p_b64}".encode(), hashlib.sha256).digest()
        s_b64 = base64.urlsafe_b64encode(sig).rstrip(b"=").decode()
        return f"{h_b64}.{p_b64}.{s_b64}", jti, exp

    @classmethod
    def decode_jwt_token(cls, token: str) -> dict:
        parts = (token or "").split(".")
        if len(parts) != 3:
            raise AuthenticationError("Formato de token JWT inválido.")
        h_b64, p_b64, s_b64 = parts
        expected_sig = hmac.new(settings.jwt_secret.encode(), f"{h_b64}.{p_b64}".encode(), hashlib.sha256).digest()
        expected_b64 = base64.urlsafe_b64encode(expected_sig).rstrip(b"=").decode()
        if not hmac.compare_digest(s_b64, expected_b64):
            raise AuthenticationError("Assinatura do token JWT inválida.")
        pad = "=" * (-len(p_b64) % 4)
        payload = json.loads(base64.urlsafe_b64decode(p_b64 + pad).decode())
        if payload.get("exp", 0) < int(datetime.now(timezone.utc).timestamp()):
            raise AuthenticationError("Token JWT expirado.")
        return payload
